function editXcodeProject(workingDirectory, bundleId, appleTeamId, profile) {
    const pbxprojPath = path.join(workingDirectory, "ios/Runner.xcodeproj/project.pbxproj");
    if (!fs.existsSync(pbxprojPath)) {
        throw new Error(`project.pbxproj not found at ${pbxprojPath}`);
    }
    let content = fs.readFileSync(pbxprojPath, "utf-8");
    content = content.replaceAll("CODE_SIGN_STYLE = Automatic;", "CODE_SIGN_STYLE = Manual;");
    content = content.replace(/DEVELOPMENT_TEAM = [^;]*;/g, `DEVELOPMENT_TEAM = ${appleTeamId};`);
    content = content
        .replaceAll('CODE_SIGN_IDENTITY = "Apple Development";', 'CODE_SIGN_IDENTITY = "Apple Distribution";')
        .replaceAll('CODE_SIGN_IDENTITY = "iPhone Developer";', 'CODE_SIGN_IDENTITY = "Apple Distribution";')
        .replaceAll('"CODE_SIGN_IDENTITY[sdk=iphoneos*]" = "iPhone Developer";', '"CODE_SIGN_IDENTITY[sdk=iphoneos*]" = "Apple Distribution";');
    content = content.replaceAll(`PRODUCT_BUNDLE_IDENTIFIER = ${bundleId};`, `PRODUCT_BUNDLE_IDENTIFIER = ${bundleId};\n\t\t\t\tPROVISIONING_PROFILE_SPECIFIER = "${profile.name}";\n\t\t\t\tPROVISIONING_PROFILE = "${profile.uuid}";`);
    fs.writeFileSync(pbxprojPath, content);
}
